"""Extract exact unique-neutral parameter tags and helper values from Steam."""
from pathlib import Path
import hashlib,json,sys
from gltf_assets import ROOT
from source2_vpk import VpkArchive
from bake_extra_heroes import kvparse
SOURCE=ROOT/'private/items/current-source';OUT=ROOT/'private/items/special-source'
def main():
 OUT.mkdir(parents=True,exist_ok=True);catalog=json.loads((SOURCE/'catalog.json').read_text(encoding='utf8'));raw=kvparse((SOURCE/'items.txt').read_text(encoding='utf-8-sig'))['DOTAAbilities'];pairs=[];aoe=[];families=[];family_names=['crude','nimble','titanic','vampiric','hulking','feverish','manic']
 for item in catalog['items']:
  for name,value in item['definition'].get('AbilityValues',{}).items():
   if isinstance(value,dict) and str(value.get('apply_curio_bonus','')).lower() in ('1','true'):pairs.append((item['id'],catalog['parameters'][name]))
   if isinstance(value,dict) and str(value.get('affected_by_aoe_increase','')).lower() in ('1','true'):aoe.append((item['id'],catalog['parameters'][name]))
  for family,name in enumerate(family_names,1):
   if item['source_name']=='item_enhancement_'+name:families.append((item['id'],family))
 archive=VpkArchive(Path('D:/Program Files (x86)/Steam/steamapps/common/dota 2 beta/game/dota/pak01_dir.vpk'));heroes=[]
 for hero in ['axe','lina','juggernaut','crystal_maiden','slark','necrolyte']:
  entry='scripts/npc/heroes/npc_dota_hero_'+hero+'.txt';unit=kvparse(archive.read(entry).decode('utf-8-sig'))['DOTAHeroes']['npc_dota_hero_'+hero];heroes.append(dict(hero=hero,minimum=int(float(unit['AttackDamageMin'])),maximum=int(float(unit['AttackDamageMax'])),source=archive.identity(entry)))
 lines=['/* Exact installed Source values/tags; generated by extract_items_special.py. */','#ifndef H1_DOTA_ITEMS_SPECIAL_VALUES_H','#define H1_DOTA_ITEMS_SPECIAL_VALUES_H','typedef struct {unsigned short item,key;} DotaSpecialParamTag;','static const DotaSpecialParamTag special_curio_tags[]={',*[f' {{{item},{key}}},' for item,key in sorted(pairs)],'};','static const DotaSpecialParamTag special_aoe_tags[]={',*[f' {{{item},{key}}},' for item,key in sorted(aoe)],'};','static const DotaSpecialParamTag special_enchantments[]={',*[f' {{{item},{family}}},' for item,family in families],'};', 'static const unsigned char special_hero_damage_span[6]={'+','.join(str(h['maximum']-h['minimum']) for h in heroes)+'};','static const unsigned char special_hero_weapon_average[6]={'+','.join(str((h['maximum']+h['minimum'])//2) for h in heroes)+'};']
 helper={}
 for name in ['item_foragers_health','item_foragers_stats','item_foragers_mana']:
  helper[name]=raw[name]
  for key,value in raw[name]['AbilityValues'].items():lines.append('#define SP_'+name.removeprefix('item_').upper()+'_'+key.upper()+'_X100 '+str(round(float(value)*100)))
 lines+=['#endif',''];path=ROOT/'game/items_special_values.h';path.write_text('\n'.join(lines),encoding='ascii')
 report=dict(complete=True,curio_tags=pairs,aoe_tags=aoe,enchantment_families=family_names,heroes=heroes,forager_helpers=helper,source_catalog_sha256=hashlib.sha256((SOURCE/'catalog.json').read_bytes()).hexdigest(),source_items_sha256=hashlib.sha256((SOURCE/'items.txt').read_bytes()).hexdigest(),generated_header_sha256=hashlib.sha256(path.read_bytes()).hexdigest())
 (OUT/'manifest.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf8');print(json.dumps(dict(curio_parameters=len(pairs),enchantment_records=len(families),hero_damage_spans=[h['maximum']-h['minimum'] for h in heroes])))
if __name__=='__main__':main()
